scenario.en:
// product page /p/42
fetch(`${CMS}/products/42`, {
  next: { tags: ['catalog:product:42', 'catalog:products'], revalidate: 3600 },
});

// category listing /products
fetch(`${CMS}/products?cat=shoes`, {
  next: { tags: ['catalog:products'], revalidate: 3600 },
});

// home page carousel
fetch(`${CMS}/featured`, {
  next: { tags: ['cms:page:home'], revalidate: 86400 },
});
// featured payload embeds product 42 with its price

// webhook handler runs exactly:
revalidateTag('catalog:product:42');

